site.script:
// Example fetch to the linked URL
fetch("https://tech-solutions.vercel.app")
	.then(response => {
		if (!response.ok) throw new Error('Network response was not ok: ' + response.status);
		return response.text();
	})
	.then(text => console.log('Fetched site length:', text.length))
	.catch(err => console.error('Fetch error:', err));
